<script setup lang="ts">
// Ventes physiques : un encaissement n'est jamais automatique, il exige la confirmation explicite du vendeur.
const props = defineProps<{ ev: any }>(); const emit = defineEmits<{ refresh: [] }>(); const toast = useToast()
const { data: features } = await useAsyncData('platform-features', () => api<Record<string, boolean>>('/api/platform/features'), { server: false })
const qty = reactive<Record<string, number>>({}); const method = ref('cash'); const received = ref(0); const holder = ref(''); const email = ref(''); const confirmed = ref(false); const busy = ref(false); const last = ref<any>(null)
const total = computed(() => props.ev.categories.reduce((s: number, c: any) => s + (qty[c.id] ?? 0) * c.price, 0)); const count = computed(() => Object.values(qty).reduce((s, n) => s + n, 0))
watch(total, (t) => { received.value = t })
const change = computed(() => Math.max(0, received.value - total.value))
const { data: orders, refresh } = await useAsyncData(`door-${props.ev.id}`, () => api<any[]>(`/api/manage/events/${props.ev.id}/orders`).catch(() => []), { server: false })
const mine = computed(() => (orders.value ?? []).filter((o) => o.channel === 'physical' && o.status === 'paid')); const cash = computed(() => mine.value.reduce((s, o) => s + o.total, 0))
const byMethod = computed(() => { const m: Record<string, number> = {}; mine.value.forEach((o) => { m[o.paymentMethod ?? 'autre'] = (m[o.paymentMethod ?? 'autre'] ?? 0) + o.total }); return Object.entries(m) })
const whatsappUrl = computed(() => last.value?.ticketUrl ? `https://wa.me/?text=${encodeURIComponent(`Billets pour ${props.ev.title} : ${last.value.ticketUrl}`)}` : '#')
async function copyTicketLink() {
  if (!last.value?.ticketUrl) return
  try { await navigator.clipboard.writeText(last.value.ticketUrl); toast.ok('Lien sécurisé copié') }
  catch { toast.err('Impossible de copier le lien. Ouvre les billets pour transmettre le lien manuellement.') }
}
async function sell() { busy.value = true; try { const items = Object.entries(qty).filter(([, n]) => n > 0).map(([categoryId, quantity]) => ({ categoryId, quantity })); last.value = await api<any>(`/api/manage/events/${props.ev.id}/door-sale`, { method: 'POST', body: { eventId: props.ev.id, items, paymentMethod: method.value, amountReceived: received.value, holderName: holder.value || 'Client guichet', buyerEmail: email.value || undefined, confirmCollected: true } }); toast.ok('Vente enregistrée et billets générés'); Object.keys(qty).forEach((k) => delete qty[k]); confirmed.value = false; holder.value = ''; email.value = ''; refresh(); emit('refresh') } catch (e) { toast.err(errMsg(e)) } finally { busy.value = false } }
async function cancel(o: any) { const reason = prompt('Motif de l’annulation ?'); if (!reason) return; try { await api(`/api/manage/orders/${o.id}/cancel`, { method: 'POST', body: { reason } }); toast.ok('Vente annulée'); refresh(); emit('refresh') } catch (e) { toast.err(errMsg(e)) } }
const methods: [string, string][] = [['cash', 'Espèces'], ['mobile_money', 'Mobile money (déjà reçu)'], ['card_terminal', 'Terminal carte'], ['other', 'Autre']]
</script>
<template>
  <div v-if="features && !features.physicalSales" class="card p-6 text-sm text-muted">Les ventes au guichet sont temporairement désactivées par l’administration TYPS.</div>
  <div v-else class="grid gap-6 xl:grid-cols-[1fr_380px]">
    <form class="card space-y-5 p-5" @submit.prevent="sell"><h2 class="text-lg font-bold">Nouvelle vente au guichet</h2>
      <ul class="space-y-2"><li v-for="c in ev.categories" :key="c.id" class="flex items-center justify-between gap-3 rounded-xl border border-line p-3"><div><p class="font-semibold">{{ c.name }}</p><p class="text-sm text-muted">{{ money(c.price, ev.currency) }} · {{ c.quota - c.sold - c.reserved }} dispo.</p></div><div class="flex items-center gap-3"><button type="button" class="btn btn-ghost !h-11 !w-11 !p-0 text-xl" :disabled="!qty[c.id]" :aria-label="`Moins ${c.name}`" @click="qty[c.id] = Math.max(0, (qty[c.id] ?? 0) - 1)">−</button><output class="w-8 text-center text-lg font-bold">{{ qty[c.id] ?? 0 }}</output><button type="button" class="btn btn-ghost !h-11 !w-11 !p-0 text-xl" :disabled="(qty[c.id] ?? 0) >= c.quota - c.sold - c.reserved" :aria-label="`Plus ${c.name}`" @click="qty[c.id] = (qty[c.id] ?? 0) + 1">+</button></div></li></ul>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="label">Moyen de paiement encaissé</span><select v-model="method" class="input"><option v-for="m in methods" :key="m[0]" :value="m[0]">{{ m[1] }}</option></select></label><label class="block"><span class="label">Montant reçu ({{ ev.currency }})</span><input v-model.number="received" type="number" min="0" class="input"></label><label class="block"><span class="label">Nom sur le billet</span><input v-model="holder" class="input" placeholder="Client guichet"></label><label class="block"><span class="label">E-mail du client (envoie le lien des billets)</span><input v-model="email" type="email" class="input"><span class="hint">Facultatif. Si renseigné, TYPS envoie le lien sécurisé après confirmation de la vente.</span></label></div>
      <div class="flex items-baseline justify-between rounded-xl bg-line/40 p-4"><span class="text-muted">À encaisser</span><span class="font-display text-3xl font-black">{{ money(total, ev.currency) }}</span></div><p v-if="received > total" class="text-sm font-semibold text-amber-300">Monnaie à rendre : {{ money(change, ev.currency) }}</p>
      <label class="flex items-start gap-3 text-sm"><input v-model="confirmed" type="checkbox" class="mt-1 h-5 w-5 accent-[rgb(var(--c-a))]"> J’ai réellement encaissé {{ money(total, ev.currency) }} ({{ methods.find((m) => m[0] === method)?.[1] }}).</label>
      <button class="btn btn-primary w-full !min-h-[56px] text-lg" :disabled="busy || !count || !confirmed || received < total">Enregistrer la vente et générer le billet</button></form>
    <div class="space-y-5"><div v-if="last" class="card space-y-4 border-emerald-500/40 p-5"><div><p class="font-bold text-emerald-300">Vente enregistrée : {{ money(last.total, last.currency) }}</p><p v-if="last.change" class="mt-1 text-sm">Monnaie : {{ money(last.change, last.currency) }}</p><p class="mt-1 text-sm text-muted">{{ last.tickets.length }} billet(s) généré(s) et prêt(s) à remettre au client.</p></div>
        <p v-if="last.emailSent === true" class="rounded-lg bg-emerald-500/10 p-3 text-sm text-emerald-200">Le lien sécurisé a été envoyé par e-mail au client.</p>
        <p v-else-if="last.emailError" class="rounded-lg bg-amber-500/10 p-3 text-sm text-amber-100">La vente est enregistrée, mais l’envoi e-mail n’a pas pu être confirmé. Copie le lien sécurisé et transmets-le au client.</p>
        <p v-else-if="last.emailSent === false" class="rounded-lg bg-amber-500/10 p-3 text-sm text-amber-100">E-mail non envoyé. Copie le lien sécurisé ou partage-le par WhatsApp.</p>
        <p v-else class="rounded-lg bg-line/30 p-3 text-sm text-muted">Aucun e-mail client indiqué. Copie le lien ou partage-le directement.</p>
        <div class="grid gap-2 sm:grid-cols-2"><button class="btn btn-primary" @click="copyTicketLink">Copier le lien client</button><a class="btn btn-ghost" :href="whatsappUrl" target="_blank" rel="noopener">Partager par WhatsApp</a><a class="btn btn-ghost sm:col-span-2" :href="`/orders/${last.orderId}?k=${encodeURIComponent(last.k)}`" target="_blank" rel="noopener">Ouvrir tous les billets</a></div>
        <div v-for="t in last.tickets" :key="t.id" class="space-y-3 rounded-xl border border-line p-3"><div class="flex flex-wrap items-center justify-between gap-2"><p class="font-mono text-sm font-bold">{{ t.ref }}</p><a class="btn btn-ghost !min-h-[38px] px-3" :href="`/api/tickets/${t.id}/pdf?k=${encodeURIComponent(last.k)}&dl=1`" target="_blank" rel="noopener">PDF</a></div><TicketView :id="t.id" :k="last.k" /></div>
        <a class="btn btn-ghost w-full" :href="`/api/orders/${last.orderId}/tickets.pdf?k=${encodeURIComponent(last.k)}`" target="_blank" rel="noopener">Planche d’impression A4</a></div>
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Caisse</h2><p class="font-display text-3xl font-black">{{ money(cash, ev.currency) }}</p><p class="text-sm text-muted">{{ mine.length }} vente(s) au guichet</p><ul class="space-y-1 text-sm"><li v-for="m in byMethod" :key="m[0]" class="flex justify-between"><span class="capitalize text-muted">{{ m[0].replace('_', ' ') }}</span><span class="font-semibold">{{ money(m[1], ev.currency) }}</span></li></ul>
        <ul class="max-h-64 divide-y divide-line overflow-y-auto text-sm"><li v-for="o in mine.slice(0, 30)" :key="o.id" class="flex items-center justify-between gap-2 py-2"><span>{{ fdate(o.paidAt, { timeStyle: 'short' }) }} · {{ o.tickets }} billet(s) · {{ money(o.total, ev.currency) }}</span><button class="text-xs text-red-300 underline" @click="cancel(o)">Annuler</button></li></ul></div></div>
  </div>
</template>
